package wslenv

import (
	"slices"
	"strings"
)

// mirroredInterface exists in the distro only under mirrored networking.
const mirroredInterface = "loopback0"

// Classify turns Facts into Info. A zero Info means "not WSL2".
func Classify(f Facts) Info {
	if !isWSL(f) || !strings.Contains(strings.ToUpper(f.OSRelease), "WSL2") {
		return Info{}
	}
	info := Info{WSL2: true}
	if f.NetworkingModeErr != nil {
		return info
	}
	hasLoopback0 := slices.Contains(f.Interfaces, mirroredInterface)
	switch strings.ToLower(strings.TrimSpace(f.NetworkingMode)) {
	case "nat":
		if hasLoopback0 {
			return info
		}
		info.Mode = ModeNAT
		if iface, gw, ok := defaultGateway(f.ProcNetRoute); ok {
			info.NATInterface = iface
			info.NATGateway = gw
		}
	case "mirrored":
		if !hasLoopback0 {
			return info
		}
		info.Mode = ModeMirrored
	}
	return info
}

// isWSL reports whether the facts describe a WSL distro (1 or 2). Either signal
// suffices: WSL_DISTRO_NAME is empty under `env -i` or from a service, and
// osrelease alone then identifies WSL.
func isWSL(f Facts) bool {
	return f.DistroName != "" || strings.Contains(strings.ToLower(f.OSRelease), "microsoft")
}
package wslenv

import (
	"errors"
	"net/netip"
	"testing"
)

const routeHeader = "Iface\tDestination\tGateway \tFlags\tRefCnt\tUse\tMetric\tMask\t\tMTU\tWindow\tIRTT\n"

// natRoutes is the spike's NAT table: default via 172.27.128.1 on eth0.
const natRoutes = routeHeader +
	"eth0\t00000000\t01801BAC\t0003\t0\t0\t0\t00000000\t0\t0\t0\n" +
	"eth0\t00801BAC\t00000000\t0001\t0\t0\t0\t00F0FFFF\t0\t0\t0\n"

func TestClassify(t *testing.T) {
	const nat = "6.18.33.2-microsoft-standard-WSL2"
	gw := netip.MustParseAddr("172.27.128.1")
	nativeIfaces := []string{"lo", "eth0"}
	mirroredIfaces := []string{"lo", "eth0", "eth1", "loopback0"}

	tests := []struct {
		name string
		in   Facts
		want Info
	}{
		{"native linux", Facts{OSRelease: "6.12.0-amd64", Interfaces: nativeIfaces}, Info{}},
		{"nat", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingMode: "nat", Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true, Mode: ModeNAT, NATInterface: "eth0", NATGateway: gw}},
		{"nat, trimmed and upper case", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingMode: " NAT\n", Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true, Mode: ModeNAT, NATInterface: "eth0", NATGateway: gw}},
		{"mirrored", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingMode: "mirrored", Interfaces: mirroredIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true, Mode: ModeMirrored}},
		{"nat reported but loopback0 present", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingMode: "nat", Interfaces: mirroredIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true}},
		{"mirrored reported but no loopback0", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingMode: "mirrored", Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true}},
		{"wslinfo error", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingModeErr: errors.New("exec: wslinfo: not found"), Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true}},
		{"virtioproxy", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingMode: "virtioproxy", Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true}},
		{"env -i: no distro name", Facts{OSRelease: nat, NetworkingMode: "nat", Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true, Mode: ModeNAT, NATInterface: "eth0", NATGateway: gw}},
		{"nat without default route", Facts{DistroName: "archlinux", OSRelease: nat, NetworkingMode: "nat", Interfaces: nativeIfaces, ProcNetRoute: []byte(routeHeader)},
			Info{WSL2: true, Mode: ModeNAT}},
		{"empty mode without error", Facts{DistroName: "archlinux", OSRelease: nat, Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{WSL2: true}},
		{"wsl1", Facts{DistroName: "Ubuntu", OSRelease: "4.4.0-19041-Microsoft", NetworkingMode: "nat", Interfaces: nativeIfaces, ProcNetRoute: []byte(natRoutes)},
			Info{}},
		{"distro name without WSL2 osrelease", Facts{DistroName: "Ubuntu", OSRelease: "6.12.0-amd64"}, Info{}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Classify(tt.in)
			if got != tt.want {
				t.Errorf("Classify() = %+v, want %+v", got, tt.want)
			}
		})
	}
}

func TestDefaultGateway(t *testing.T) {
	tests := []struct {
		name      string
		route     string
		wantIface string
		wantGW    string
		wantOK    bool
	}{
		{"little endian", natRoutes, "eth0", "172.27.128.1", true},
		{"lowest metric wins", routeHeader +
			"eth3\t00000000\t0101A8C0\t0003\t0\t0\t25\t00000000\t0\t0\t0\n" +
			"eth0\t00000000\t01801BAC\t0003\t0\t0\t1\t00000000\t0\t0\t0\n" +
			"eth1\t00000000\t0201A8C0\t0003\t0\t0\t50\t00000000\t0\t0\t0\n", "eth0", "172.27.128.1", true},
		{"non default routes ignored", routeHeader +
			"eth0\t00801BAC\t00000000\t0001\t0\t0\t0\t00F0FFFF\t0\t0\t0\n" +
			"eth3\t00000000\t0101A8C0\t0003\t0\t0\t25\t00000000\t0\t0\t0\n", "eth3", "192.168.1.1", true},
		{"no route", "", "", "", false},
		{"invalid gateway, 8 chars", routeHeader +
			"eth0\t00000000\tZZZZZZZZ\t0003\t0\t0\t0\t00000000\t0\t0\t0\n", "", "", false},
		{"invalid gateway, 7 chars", routeHeader +
			"eth0\t00000000\t01801BA\t0003\t0\t0\t0\t00000000\t0\t0\t0\n", "", "", false},
		{"zero gateway with lowest metric", routeHeader +
			"eth0\t00000000\t00000000\t0003\t0\t0\t1\t00000000\t0\t0\t0\n" +
			"eth3\t00000000\t0101A8C0\t0003\t0\t0\t25\t00000000\t0\t0\t0\n", "", "", false},
		{"non numeric metric", routeHeader +
			"eth0\t00000000\t01801BAC\t0003\t0\t0\tabc\t00000000\t0\t0\t0\n", "", "", false},
		{"equal metrics, first wins", routeHeader +
			"eth3\t00000000\t0101A8C0\t0003\t0\t0\t5\t00000000\t0\t0\t0\n" +
			"eth0\t00000000\t01801BAC\t0003\t0\t0\t5\t00000000\t0\t0\t0\n", "eth3", "192.168.1.1", true},
		{"header only", routeHeader, "", "", false},
		{"no default route", routeHeader +
			"eth0\t00801BAC\t00000000\t0001\t0\t0\t0\t00F0FFFF\t0\t0\t0\n", "", "", false},
		{"malformed line", routeHeader + "eth0\t00000000\tZZZZ\n", "", "", false},
		{"truncated line", routeHeader + "eth0\t00000000\n", "", "", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			iface, gw, ok := defaultGateway([]byte(tt.route))
			if ok != tt.wantOK {
				t.Fatalf("ok = %v, want %v", ok, tt.wantOK)
			}
			if !ok {
				return
			}
			if iface != tt.wantIface || gw != netip.MustParseAddr(tt.wantGW) {
				t.Errorf("got (%q, %v), want (%q, %s)", iface, gw, tt.wantIface, tt.wantGW)
			}
		})
	}
}
package wslenv

import (
	"encoding/hex"
	"net/netip"
	"strconv"
	"strings"
)

// Column positions in /proc/net/route.
const (
	colIface   = 0
	colDest    = 1
	colGateway = 2
	colMetric  = 6
	routeCols  = 7
)

// defaultGateway returns the interface and gateway of the default route with
// the lowest metric in a /proc/net/route dump (the first one on equal
// metrics). ok is false when there is no such route, or when that route has no
// gateway (0.0.0.0): a higher-metric route is never used instead. Lines with
// too few columns, an undecodable gateway or a non-numeric metric are skipped.
func defaultGateway(procNetRoute []byte) (iface string, gw netip.Addr, ok bool) {
	var best uint64
	for _, line := range strings.Split(string(procNetRoute), "\n") {
		f := strings.Fields(line)
		if len(f) < routeCols || f[colDest] != "00000000" {
			continue
		}
		addr, valid := parseLEAddr(f[colGateway])
		if !valid {
			continue
		}
		metric, err := strconv.ParseUint(f[colMetric], 10, 32)
		if err != nil {
			continue
		}
		if !ok || metric < best {
			iface, gw, best, ok = f[colIface], addr, metric, true
		}
	}
	if !ok || gw.IsUnspecified() {
		return "", netip.Addr{}, false
	}
	return iface, gw, true
}

// parseLEAddr decodes the little-endian hex IPv4 address used by /proc/net/route.
func parseLEAddr(s string) (netip.Addr, bool) {
	b, err := hex.DecodeString(s)
	if err != nil || len(b) != 4 {
		return netip.Addr{}, false
	}
	return netip.AddrFrom4([4]byte{b[3], b[2], b[1], b[0]}), true
}
// Package wslenv detects WSL2 and its networking mode from plain facts.
package wslenv

import "net/netip"

// Mode is the WSL2 networking mode.
type Mode int

const (
	// ModeUndetermined is the zero value: the mode could not be established.
	ModeUndetermined Mode = iota
	// ModeNAT is the default WSL2 mode (virtual switch).
	ModeNAT
	// ModeMirrored mirrors the Windows interfaces into the distro.
	ModeMirrored
)

// Facts are the raw observations Classify decides from.
type Facts struct {
	DistroName        string
	OSRelease         string
	NetworkingMode    string
	NetworkingModeErr error
	Interfaces        []string
	ProcNetRoute      []byte
}

// Info is the classification of Facts.
type Info struct {
	WSL2         bool
	Mode         Mode
	NATInterface string
	// NATGateway is the zero Addr when unknown (mode not NAT, or no usable
	// default route): consumers must test NATGateway.IsValid().
	NATGateway netip.Addr
}
package nettrace

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"strconv"
	"strings"
	"testing"
)

// The trace sends its probes itself, over ICMP and UDP sockets. It must never
// start a child process (traceroute, ping) nor replace the process image, on
// any platform. The guard reads every .go file of the package whatever its
// build constraints (go/parser does not evaluate them), so a file that only
// builds on another OS is covered too.

// bannedImports are packages that must not be imported at all.
var bannedImports = map[string]bool{
	"os/exec":                  true,
	"golang.org/x/sys/execabs": true,
}

// dotWatched are packages that must not be dot-imported: a dot-import hides
// the package name the selector check relies on.
var dotWatched = map[string]bool{
	"os":                    true,
	"syscall":               true,
	"os/exec":               true,
	"golang.org/x/sys/unix": true,
}

// bannedSymbols maps an import path to the process-launching symbols it must
// not expose here, called or not (`f := os.StartProcess` is caught too). The
// socket symbols the engine needs (Recvmsg, Setsockopt...) stay allowed.
var bannedSymbols = map[string]map[string]bool{
	"os": {"StartProcess": true},
	"syscall": {
		"StartProcess": true, "ForkExec": true, "Exec": true,
		"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
	},
	"golang.org/x/sys/unix": {
		"Exec":    true,
		"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
	},
}

// guardSource returns one message per offence in src ("name:line: ...").
func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
	file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	var out []string
	local := map[string]string{} // local package name -> import path
	for _, imp := range file.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		if bannedImports[path] {
			out = append(out, fmt.Sprintf("%s: import of %s", fset.Position(imp.Pos()), path))
		}
		if imp.Name != nil && imp.Name.Name == "." && dotWatched[path] {
			out = append(out, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
		}
		if _, watched := bannedSymbols[path]; !watched {
			continue
		}
		n := path[strings.LastIndex(path, "/")+1:]
		if imp.Name != nil {
			n = imp.Name.Name
		}
		local[n] = path
	}
	ast.Inspect(file, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		id, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		if path, ok := local[id.Name]; ok && bannedSymbols[path][sel.Sel.Name] {
			out = append(out, fmt.Sprintf("%s: use of %s.%s", fset.Position(sel.Pos()), id.Name, sel.Sel.Name))
		}
		return true
	})
	return out, nil
}

func TestGuardSourceFlagsOffences(t *testing.T) {
	for _, c := range []struct {
		name, src string
		want      int
	}{
		{"exec.go", "package x\nimport \"os/exec\"\nfunc f() { _ = exec.Command(\"traceroute\") }\n", 1},
		{"aliased_exec.go", "package x\nimport e \"os/exec\"\nvar _ = e.Command\n", 1},
		{"startprocess.go", "package x\nimport \"os\"\nfunc f() { _, _ = os.StartProcess(\"a\", nil, nil) }\n", 1},
		{"forkexec.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.ForkExec(\"a\", nil, nil); _ = syscall.Exec(\"a\", nil, nil) }\n", 2},
		{"unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Exec(\"a\", nil, nil) }\n", 1},
		{"aliased_unix.go", "package x\nimport u \"golang.org/x/sys/unix\"\nfunc f() { _ = u.Exec(\"a\", nil, nil) }\n", 1},
		{"tagged.go", "//go:build windows\n\npackage x\nimport \"os/exec\"\nvar _ = exec.Command\n", 1},
		{"execabs.go", "package x\nimport \"golang.org/x/sys/execabs\"\nvar _ = execabs.Command\n", 1},
		{"syscall_startprocess.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.StartProcess(\"a\", nil, nil) }\n", 1},
		{"raw_syscall.go", "package x\nimport \"syscall\"\nfunc f() { syscall.RawSyscall(59, 0, 0); syscall.Syscall(59, 0, 0, 0); syscall.Syscall6(59, 0, 0, 0, 0, 0, 0); syscall.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 4},
		{"unix_syscall.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { unix.Syscall(59, 0, 0, 0); unix.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 2},
		{"func_value.go", "package x\nimport \"os\"\nvar f = os.StartProcess\n", 1},
		{"dot_os.go", "package x\nimport . \"os\"\nvar _ = Getpid\n", 1},
		{"dot_syscall.go", "package x\nimport . \"syscall\"\nvar _ = Getpid\n", 1},
		{"dot_exec.go", "package x\nimport . \"os/exec\"\nvar _ = Command\n", 2},
		{"dot_unix.go", "package x\nimport . \"golang.org/x/sys/unix\"\nvar _ = Getpid\n", 1},
		{"allowed_unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Setsockopt; _ = unix.Recvmsg }\n", 0},
		{"clean.go", "package x\nimport (\"os\"; \"syscall\")\n// os.StartProcess in a comment is not a call\nfunc f() { _ = os.Getpid(); _ = syscall.Getpid(); var s struct{ Exec func() }; s.Exec() }\n", 0},
	} {
		got, err := guardSource(token.NewFileSet(), c.name, c.src)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if len(got) != c.want {
			t.Errorf("%s: got %d offences %v, want %d", c.name, len(got), got, c.want)
		}
	}
}

func TestPackageNeverStartsAProcess(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	fset := token.NewFileSet()
	files := 0
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		src, err := os.ReadFile(e.Name())
		if err != nil {
			t.Fatal(err)
		}
		files++
		offences, err := guardSource(fset, e.Name(), src)
		if err != nil {
			t.Errorf("%s: %v", e.Name(), err)
			continue
		}
		for _, o := range offences {
			t.Error(o + ": the trace must not start or exec a process")
		}
	}
	if files == 0 {
		t.Error("the scan saw no Go file: the guard would pass vacuously")
	}
}

