type fakeProbe struct {
	goos      string
	env       map[string]string
	files     map[string][]byte
	fileErr   map[string]error
	ifaces    []string
	ifaceErr  error
	mode      string
	modeErr   error
	reads     []string
	getenvs   []string
	ifaceN    int
	modeCalls int
