	wslRelease    = "6.18.33.2-microsoft-standard-WSL2\n"
	nativeRelease = "6.12.0-amd64\n"
	osreleasePath = "/proc/sys/kernel/osrelease"
	routePath     = "/proc/net/route"
)

// fakeProbe records every call so a test can assert what was (not) read.
type fakeProbe struct {
	goos      string
	env       map[string]string
	files     map[string][]byte
	fileErr   map[string]error
	ifaces    []string
	ifaceErr  error
	mode      string
	modeErr   error
	reads     []string
	getenvs   []string
	ifaceN    int
	modeCalls int
}

func (f *fakeProbe) probe() Probe {
	return Probe{
		GOOS:   f.goos,
		Getenv: func(k string) string { f.getenvs = append(f.getenvs, k); return f.env[k] },
		ReadFile: func(p string) ([]byte, error) {
			f.reads = append(f.reads, p)
			if err := f.fileErr[p]; err != nil {
				return nil, err
			}
			return f.files[p], nil
		},
		InterfaceNames: func() ([]string, error) { f.ifaceN++; return f.ifaces, f.ifaceErr },
		NetworkingMode: func(ctx context.Context) (string, error) {
			f.modeCalls++
			if err := ctx.Err(); err != nil {
				return "", err
			}
			return f.mode, f.modeErr
		},
	}
}

func (f *fakeProbe) read(path string) bool { return slices.Contains(f.reads, path) }

func wslFake() *fakeProbe {
	return &fakeProbe{
		goos:   "linux",
		env:    map[string]string{"WSL_DISTRO_NAME": "archlinux"},
		files:  map[string][]byte{osreleasePath: []byte(wslRelease), routePath: []byte(natRoutes)},
		ifaces: []string{"lo", "eth0"},
		mode:   "nat",
	}
}

func TestGatherNotLinuxProbesNothing(t *testing.T) {
	for _, goos := range []string{"windows", "darwin", ""} {
		f := wslFake()
		f.goos = goos
		got := Gather(context.Background(), f.probe())
		if got.DistroName != "" || got.OSRelease != "" || got.NetworkingMode != "" ||
			got.NetworkingModeErr != nil || len(got.Interfaces) != 0 || len(got.ProcNetRoute) != 0 {
			t.Errorf("GOOS=%q: Facts = %+v, want empty", goos, got)
		}
		if len(f.reads)+len(f.getenvs)+f.ifaceN+f.modeCalls != 0 {
			t.Errorf("GOOS=%q: probe called (reads=%v getenv=%v ifaces=%d mode=%d)", goos, f.reads, f.getenvs, f.ifaceN, f.modeCalls)
		}
	}
}

func TestGatherNativeLinuxSkipsWSLReads(t *testing.T) {
	f := wslFake()
	f.env = map[string]string{}
	f.files[osreleasePath] = []byte(nativeRelease)
	got := Gather(context.Background(), f.probe())
	if !f.read(osreleasePath) {
		t.Errorf("osrelease not read: reads=%v", f.reads)
	}
	if f.modeCalls != 0 {
		t.Errorf("NetworkingMode called %d times on native Linux", f.modeCalls)
	}
	if f.read(routePath) {
		t.Errorf("%s read on native Linux", routePath)
	}
	if got.NetworkingMode != "" || got.NetworkingModeErr != nil || len(got.ProcNetRoute) != 0 {
		t.Errorf("Facts = %+v, want no WSL facts", got)
	}
	if !strings.Contains(got.OSRelease, "6.12.0-amd64") {
		t.Errorf("OSRelease = %q", got.OSRelease)
	}
	if Classify(got) != (Info{}) {
		t.Errorf("Classify = %+v, want zero", Classify(got))
	}
}

func TestGatherWSLSignals(t *testing.T) {
	tests := []struct {
		name    string
		env     map[string]string
		release string
	}{
		{"distro name", map[string]string{"WSL_DISTRO_NAME": "archlinux"}, wslRelease},
		{"osrelease only (env -i)", map[string]string{}, wslRelease},
		{"distro name, plain osrelease", map[string]string{"WSL_DISTRO_NAME": "Ubuntu"}, nativeRelease},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			f := wslFake()
			f.env = tt.env
			f.files[osreleasePath] = []byte(tt.release)
			got := Gather(context.Background(), f.probe())
			if f.modeCalls != 1 {
				t.Errorf("NetworkingMode calls = %d, want 1", f.modeCalls)
			}
			if !f.read(osreleasePath) || !f.read(routePath) {
				t.Errorf("reads = %v, want osrelease and route", f.reads)
			}
			if f.ifaceN != 1 {
				t.Errorf("InterfaceNames calls = %d, want 1", f.ifaceN)
			}
			if got.DistroName != tt.env["WSL_DISTRO_NAME"] {
				t.Errorf("DistroName = %q", got.DistroName)
			}
			if strings.TrimSpace(got.OSRelease) != strings.TrimSpace(tt.release) {
				t.Errorf("OSRelease = %q", got.OSRelease)
			}
			if got.NetworkingMode != "nat" || got.NetworkingModeErr != nil {
				t.Errorf("mode = %q err = %v", got.NetworkingMode, got.NetworkingModeErr)
			}
			if strings.Join(got.Interfaces, ",") != "lo,eth0" {
				t.Errorf("Interfaces = %v", got.Interfaces)
			}
			if string(got.ProcNetRoute) != natRoutes {
				t.Errorf("ProcNetRoute = %q", got.ProcNetRoute)
			}
		})
	}
}

func TestGatherEndToEndClassify(t *testing.T) {
	f := wslFake()
	got := Classify(Gather(context.Background(), f.probe()))
	want := Info{WSL2: true, Mode: ModeNAT, NATInterface: "eth0", NATGateway: netip.MustParseAddr("172.27.128.1")}
	if got != want {
		t.Errorf("Classify(Gather) = %+v, want %+v", got, want)
	}
}

func TestGatherReadErrorsGiveEmptyValues(t *testing.T) {
	boom := errors.New("boom")

	f := wslFake()
	f.fileErr = map[string]error{osreleasePath: boom}
	got := Gather(context.Background(), f.probe())
	if got.OSRelease != "" {
		t.Errorf("OSRelease = %q on read error, want empty", got.OSRelease)
	}
	if got.DistroName != "archlinux" {
		t.Errorf("DistroName = %q, want archlinux (env still identifies WSL)", got.DistroName)
	}

	f = wslFake()
	f.fileErr = map[string]error{routePath: boom}
	f.files[routePath] = []byte("partial")
	got = Gather(context.Background(), f.probe())
	if len(got.ProcNetRoute) != 0 {
		t.Errorf("ProcNetRoute = %q on read error, want empty", got.ProcNetRoute)
	}
	if got.NetworkingMode != "nat" {
		t.Errorf("a route read error must not affect the mode: %q", got.NetworkingMode)
	}

	f = wslFake()
	f.ifaceErr = boom
	f.ifaces = []string{"lo"}
	got = Gather(context.Background(), f.probe())
	if len(got.Interfaces) != 0 {
		t.Errorf("Interfaces = %v on error, want empty", got.Interfaces)
	}
}

func TestGatherNetworkingModeError(t *testing.T) {
	f := wslFake()
	f.modeErr = errors.New("exec: wslinfo: not found")
	got := Gather(context.Background(), f.probe())
	if got.NetworkingModeErr == nil {
		t.Fatal("NetworkingModeErr = nil, want the probe error")
	}
	if info := Classify(got); !info.WSL2 || info.Mode != ModeUndetermined {
		t.Errorf("Classify = %+v, want WSL2 with undetermined mode", info)
	}
}

func TestGatherCancelledContext(t *testing.T) {
	f := wslFake()
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	got := Gather(ctx, f.probe())
	if got.NetworkingModeErr == nil {
		t.Fatal("NetworkingModeErr = nil on a cancelled context")
	}
	if info := Classify(got); !info.WSL2 || info.Mode != ModeUndetermined {
		t.Errorf("Classify = %+v, want WSL2 with undetermined mode", info)
	}
}

func TestParseWslinfoOutput(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"plain", "nat", "nat"},
		{"trailing newline", "mirrored\n", "mirrored"},
		{"crlf", "nat\r\n", "nat"},
		{"surrounding spaces", "  virtioproxy \t\n", "virtioproxy"},
		{"empty", "", ""},
		{"only spaces", " \n\t ", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := parseWslinfoOutput([]byte(tt.in)); got != tt.want {
				t.Errorf("parseWslinfoOutput(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

func TestParseWslinfoOutputIsBounded(t *testing.T) {
	long := strings.Repeat("a", 500) + "\n"
	got := parseWslinfoOutput([]byte(long))
	if len(got) == 0 || len(got) > 64 {
		t.Fatalf("len = %d, want 1..64", len(got))
	}
	if strings.Trim(got, "a") != "" {
		t.Errorf("output %q is not a prefix of the input", got)
	}
	// Padding must neither push the value out of the window nor survive trimming.
	if got := parseWslinfoOutput([]byte("nat" + strings.Repeat(" ", 200))); got != "nat" {
		t.Errorf("padded = %q, want nat", got)
	}
}

package wslenv

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// The detection reads files and runs one fixed program. It must never reach
// the network, and the only child process is wslinfo, started from wslinfo.go
// by absolute path. The guard reads every non-test .go file whatever its build
// constraints (go/parser does not evaluate them).

const wslinfoFile = "wslinfo.go"

// networkImports are packages that must not be imported at all.
var networkImports = map[string]bool{
	"net/http": true, "net/rpc": true, "net/smtp": true, "net/textproto": true,
	"net/http/httputil": true, "crypto/tls": true,
	"github.com/libp2p/go-netroute": true,
}

// bannedNetSymbols are the symbols of "net" that open a connection or resolve
// a name. Interface enumeration (net.Interfaces) stays allowed.
var bannedNetSymbols = map[string]bool{
	"Dial": true, "DialTimeout": true, "Dialer": true, "Listen": true, "ListenPacket": true,
	"ListenConfig": true, "ListenTCP": true, "ListenUDP": true, "DialTCP": true, "DialUDP": true,
	"DialIP": true, "Resolver": true, "DefaultResolver": true, "LookupHost": true, "LookupIP": true,
	"LookupAddr": true, "LookupCNAME": true, "LookupPort": true, "LookupTXT": true, "LookupMX": true,
	"LookupNS": true, "LookupSRV": true, "ResolveTCPAddr": true, "ResolveUDPAddr": true, "ResolveIPAddr": true,
}

type fileFacts struct {
	imports  map[string]string // local name -> path
	literals []string          // string literals, in source order
	selects  []string          // "path.Sym" selector expressions on imported packages
	offences []string
}

func scan(fset *token.FileSet, name string, src any) (*fileFacts, error) {
	file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	ff := &fileFacts{imports: map[string]string{}}
	for _, imp := range file.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		local := path[strings.LastIndex(path, "/")+1:]
		if imp.Name != nil {
			local = imp.Name.Name
			if local == "." {
				ff.offences = append(ff.offences, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
			}
		}
		ff.imports[local] = path
		if networkImports[path] || strings.HasPrefix(path, "golang.org/x/net") {
			ff.offences = append(ff.offences, fmt.Sprintf("%s: network import %s", fset.Position(imp.Pos()), path))
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.BasicLit:
			if x.Kind == token.STRING {
				s, _ := strconv.Unquote(x.Value)
				ff.literals = append(ff.literals, s)
			}
		case *ast.SelectorExpr:
			id, ok := x.X.(*ast.Ident)
			if !ok {
				return true
			}
			path, ok := ff.imports[id.Name]
			if !ok {
				return true
			}
			ff.selects = append(ff.selects, path+"."+x.Sel.Name)
			if path == "net" && bannedNetSymbols[x.Sel.Name] {
				ff.offences = append(ff.offences, fmt.Sprintf("%s: use of net.%s", fset.Position(x.Pos()), x.Sel.Name))
			}
		}
		return true
	})
	return ff, nil
}

func (ff *fileFacts) importsPath(path string) bool {
	for _, p := range ff.imports {
		if p == path {
			return true
		}
	}
	return false
}

// wslinfoOffences checks the one file allowed to start a process.
func wslinfoOffences(ff *fileFacts) []string {
	var out []string
	if !ff.importsPath("os/exec") {
		out = append(out, wslinfoFile+": does not import os/exec")
	}
	var paths []string
	for _, l := range ff.literals {
		if strings.HasPrefix(l, "/") {
			paths = append(paths, l)
		}
	}
	if got, want := strings.Join(paths, " "), "/usr/bin/wslinfo /usr/sbin/wslinfo"; got != want {
		out = append(out, fmt.Sprintf("%s: absolute path literals are %q, want exactly %q in that order", wslinfoFile, got, want))
	}
	hasArg := false
	for _, l := range ff.literals {
		if l == "--networking-mode" {
			hasArg = true
		}
		if strings.Contains(l, "PATH") {
			out = append(out, fmt.Sprintf("%s: literal %q reads PATH", wslinfoFile, l))
		}
	}
	if !hasArg {
		out = append(out, wslinfoFile+": constant argument --networking-mode not found")
	}
	for _, s := range ff.selects {
		switch s {
		case "os/exec.LookPath", "os.Getenv", "os.LookupEnv", "os.Environ":
			out = append(out, fmt.Sprintf("%s: use of %s (no PATH lookup)", wslinfoFile, s))
		}
	}
	return out
}

func TestGuardScanFlagsOffences(t *testing.T) {
	for _, c := range []struct {
		name, src string
		want      int
	}{
		{"http.go", "package x\nimport \"net/http\"\nvar _ = http.Get\n", 1},
		{"xnet.go", "package x\nimport \"golang.org/x/net/icmp\"\nvar _ = icmp.ListenPacket\n", 1},
		{"dial.go", "package x\nimport \"net\"\nfunc f() { _, _ = net.Dial(\"tcp\", \"a:1\") }\n", 1},
		{"lookup.go", "package x\nimport \"net\"\nfunc f() { _, _ = net.LookupHost(\"a\") }\n", 1},
		{"dot.go", "package x\nimport . \"net\"\nvar _ = Interfaces\n", 1},
		{"ifaces.go", "package x\nimport \"net\"\nvar _ = net.Interfaces\n", 0},
		{"clean.go", "package x\nimport \"os\"\n// net.Dial in a comment\nvar _ = os.ReadFile\n", 0},
	} {
		ff, err := scan(token.NewFileSet(), c.name, c.src)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if len(ff.offences) != c.want {
			t.Errorf("%s: got %v, want %d offences", c.name, ff.offences, c.want)
		}
	}

	const consts = "var a, b, c = \"/usr/bin/wslinfo\", \"/usr/sbin/wslinfo\", \"--networking-mode\"\n"
	good := "package x\nimport \"os/exec\"\nvar _ = exec.CommandContext\n" + consts
	ff, err := scan(token.NewFileSet(), wslinfoFile, good)
	if err != nil {
		t.Fatal(err)
	}
	if o := wslinfoOffences(ff); len(o) != 0 {
		t.Errorf("good wslinfo.go flagged: %v", o)
	}
	for name, src := range map[string]string{
		"lookpath":  "package x\nimport \"os/exec\"\nvar _ = exec.LookPath\n" + consts,
		"bare name": "package x\nimport \"os/exec\"\nvar a, c = \"wslinfo\", \"--networking-mode\"\n",
		"extra":     "package x\nimport \"os/exec\"\nvar a, b, d, c = \"/usr/bin/wslinfo\", \"/usr/sbin/wslinfo\", \"/bin/sh\", \"--networking-mode\"\n",
		"order":     "package x\nimport \"os/exec\"\nvar a, b, c = \"/usr/sbin/wslinfo\", \"/usr/bin/wslinfo\", \"--networking-mode\"\n",
		"no arg":    "package x\nimport \"os/exec\"\nvar a, b = \"/usr/bin/wslinfo\", \"/usr/sbin/wslinfo\"\n",
		"path":      "package x\nimport \"os/exec\"\n" + consts + "var p = \"PATH\"\n",
		"no exec":   "package x\n" + consts,
	} {
		ff, err := scan(token.NewFileSet(), wslinfoFile, src)
		if err != nil {
			t.Fatal(err)
		}
		if len(wslinfoOffences(ff)) == 0 {
			t.Errorf("wslinfo.go variant %q not flagged", name)
		}
	}
}

func TestPackageSourceGuard(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, e := range entries {
		n := e.Name()
		if !e.IsDir() && strings.HasSuffix(n, ".go") && !strings.HasSuffix(n, "_test.go") {
			names = append(names, n)
		}
	}
	sort.Strings(names)
	if len(names) == 0 {
		t.Fatal("the scan saw no Go file: the guard would pass vacuously")
	}
	fset := token.NewFileSet()
	for _, n := range names {
		src, err := os.ReadFile(n)
		if err != nil {
			t.Fatal(err)
		}
		ff, err := scan(fset, n, src)
		if err != nil {
			t.Errorf("%s: %v", n, err)
			continue
		}
		for _, o := range ff.offences {
			t.Error(o)
		}
		if n == wslinfoFile {
			for _, o := range wslinfoOffences(ff) {
				t.Error(o)
			}
			continue
		}
		if ff.importsPath("os/exec") || ff.importsPath("golang.org/x/sys/execabs") {
			t.Errorf("%s: imports os/exec; only %s may start a process", n, wslinfoFile)
		}
	}
}
